                         'let mut counter = 0\n'
                         '## Adds to the shared counter.\n'
                         'let bump n =\n'
                         '  counter <- counter + n\n'
                         '  counter\n'
                         'let pure double x = x * 2\n'
                         'let (|Even|Odd|) n = if n % 2 == 0 then Even else Odd\n'
                         'let (|Positive|_|) n = if n > 0 then Some n else None\n'
                         'let kind n =\n'
                         '  match n:\n'
                         '    case Even: "even"\n'
                         '    case Odd: "odd"\n'
                         'let pos n =\n'
                         '  match n:\n'
                         '    case Positive p: p\n'
                         '    case _: 0\n'
                         'extern runAsync: Async a -> a = asyncio.run\n'
                         'let fetch x = async { return x + 1 }\n'
                         'let both x =\n'
                         '  async {\n'
                         '    let! a = fetch x\n'
                         '    let! b = fetch a\n'
                         '    return a + b\n'
                         '  }\n'
                         'let todo x = x + ?gap\n',
