@pytest.mark.parametrize("case", SITE_CASES, ids=[c["id"] for c in SITE_CASES])
def test_feature_sites_in_declaring_and_using_modules(run, workdir, case):
    """CATCHES: hover types/effects/units, definitions, references or renames of feature
    declarations and their cross-module uses that differ from the reference server."""
    S.check(run, workdir, case, __file__)


@pytest.mark.parametrize("case", COMPLETION_CASES, ids=[c["id"] for c in COMPLETION_CASES])
def test_completion_after_library_qualifier(run, workdir, case):
    """CATCHES: library member completion (externs, builders, units, async) that differs."""
    S.check(run, workdir, case, __file__)


@pytest.mark.parametrize("case", BREAK_CASES, ids=[c["id"] for c in BREAK_CASES])
def test_diagnostics_when_a_library_feature_breaks(run, workdir, case):
    """CATCHES: the using module analysed against a stale library, or a broken feature
    reported differently (buffer vs disk)."""
    S.check(run, workdir, case, __file__)
